#!/usr/bin/env bash
# Draft only. Continue the exact failed 4d1 staging surface after controller review.
set -euo pipefail
umask 077
readonly ROOT=/var/lib/orloom/c3-suite-memory-20261013
readonly INCOMING=$ROOT.corrected-incoming
readonly OLD_INCOMING=$ROOT.incoming
readonly OLD_NODE=/var/lib/orloom/c3-suite-proof-20261013/staging/node NODE_SHA=d1de76d8edf2fededf6f8b30d244e2c0529ac607923a018283b77e9c74bd932c
readonly CANDIDATE=4d1dd56b4d16990a6b3222a40bd53ed5ddef3e5a BASE=6b4d6832cfa2e58997fc1e0d1d0a22fa68ba1af9
readonly MANIFEST=dc127e92f0bef9e9b2d0b8ad4cbf7a73d69d673e15e4e1b765ceceabac2bab28
readonly REF=refs/heads/feat/trusted-verification-suite

[[ ${EUID:-$(id -u)} -eq 0 && $# -eq 0 ]] || { echo 'usage: root finish-stage-memory.sh' >&2; exit 64; }
[[ -d "$ROOT" && ! -L "$ROOT" && -d "$OLD_INCOMING" && ! -L "$OLD_INCOMING" && -d "$INCOMING" && ! -L "$INCOMING" ]] || { echo 'continuation roots are unsafe' >&2; exit 73; }
[[ -d "$ROOT/source.git" && ! -L "$ROOT/source.git" && -d "$ROOT/source" && ! -L "$ROOT/source" ]] || { echo 'partial source clone is missing or unsafe' >&2; exit 73; }
for absent in runtime-files runtime-acceptance.mjs cgroup-observer.mjs runtime-acceptance-entry.mjs runtime-snapshot-export.mjs export-acceptance-snapshot.sh prepare-acceptance-fixtures.mjs stage-bindings.json runtime-started.json verifier-image.id image-binding.json fixtures; do [[ ! -e "$ROOT/$absent" && ! -L "$ROOT/$absent" ]] || { echo "prior payload/runtime state exists: $absent" >&2; exit 75; }; done
[[ ! -e "$ROOT/staging/node" && ! -L "$ROOT/staging/node" && -f "$OLD_NODE" && ! -L "$OLD_NODE" && $(sha256sum "$OLD_NODE" | cut -d' ' -f1) == "$NODE_SHA" ]] || { echo 'staging node state is unsafe' >&2; exit 69; }

gitc(){ env -i PATH=/usr/bin:/bin HOME=/root GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_SYSTEM=/dev/null GIT_TERMINAL_PROMPT=0 git "$@"; }
[[ $(gitc --git-dir="$ROOT/source.git" rev-parse "$REF^{commit}") == "$CANDIDATE" && $(gitc --git-dir="$ROOT/source.git" cat-file -t "$CANDIDATE") == commit && $(gitc --git-dir="$ROOT/source.git" merge-base "$BASE" "$CANDIDATE") == "$BASE" ]] || { echo 'bare repository identity differs' >&2; exit 65; }
[[ ! -e "$ROOT/source.git/objects/info/alternates" && ! -e "$ROOT/source.git/shallow" && $(gitc -C "$ROOT/source" rev-parse HEAD) == "$CANDIDATE" && -z $(gitc -C "$ROOT/source" status --porcelain=v1) ]] || { echo 'materialized source identity differs' >&2; exit 65; }
committed_manifest=$(gitc -C "$ROOT/source" show "$CANDIDATE:.agent/ORL-C3-SUITE-MANIFEST.sha256" | sha256sum | cut -d' ' -f1)
[[ $committed_manifest == "$MANIFEST" && $(sha256sum "$ROOT/source/.agent/ORL-C3-SUITE-MANIFEST.sha256" | cut -d' ' -f1) == "$MANIFEST" ]] || { echo 'committed or materialized manifest hash differs' >&2; exit 65; }
cmp -s <(gitc -C "$ROOT/source" show "$CANDIDATE:.agent/ORL-C3-SUITE-MANIFEST.sha256") "$ROOT/source/.agent/ORL-C3-SUITE-MANIFEST.sha256" || { echo 'materialized manifest bytes differ from committed LF blob' >&2; exit 65; }
[[ $(wc -l < "$ROOT/source/.agent/ORL-C3-SUITE-MANIFEST.sha256") == 117 ]] || { echo 'manifest entry count differs' >&2; exit 65; }
while IFS= read -r row; do [[ $row =~ ^([a-f0-9]{64})\ \ (.+)$ ]] || exit 65; hash=${BASH_REMATCH[1]}; rel=${BASH_REMATCH[2]}; [[ $rel != /* && $rel != *'..'* && -f "$ROOT/source/$rel" && ! -L "$ROOT/source/$rel" && $(sha256sum "$ROOT/source/$rel" | cut -d' ' -f1) == "$hash" ]] || { echo "source manifest mismatch: $rel" >&2; exit 65; }; done < "$ROOT/source/.agent/ORL-C3-SUITE-MANIFEST.sha256"

for f in candidate.bundle candidate-identity.json stage-bindings.json runtime-acceptance.mjs cgroup-observer.mjs runtime-acceptance-entry.mjs runtime-snapshot-export.mjs export-acceptance-snapshot.sh prepare-acceptance-fixtures.mjs; do [[ -f "$INCOMING/$f" && ! -L "$INCOMING/$f" ]] || { echo "missing corrected incoming $f" >&2; exit 66; }; done
[[ -d "$INCOMING/runtime-files" && ! -L "$INCOMING/runtime-files" && -f "$INCOMING/runtime-files/runtime-files.sha256" && ! -L "$INCOMING/runtime-files/runtime-files.sha256" && -f "$INCOMING/runtime-files/runtime-files-identity.json" && ! -L "$INCOMING/runtime-files/runtime-files-identity.json" ]] || { echo 'corrected runtime payload is incomplete' >&2; exit 66; }
jq -e 'type=="object" and (keys|sort)==["approvedRef","baseSha","candidateSha","fixtureHelperSha256","observerHelperSha256","runtimeEntrySha256","runtimeHelperSha256","runtimePayloadSha256","runtimeSnapshotSha256","runtimeSnapshotShellSha256","sourceManifestSha256"] and .approvedRef==$ref and .baseSha==$base and .candidateSha==$candidate and .sourceManifestSha256==$manifest and (.runtimePayloadSha256|test("^[a-f0-9]{64}$")) and (.runtimeHelperSha256|test("^[a-f0-9]{64}$")) and (.observerHelperSha256|test("^[a-f0-9]{64}$")) and (.runtimeEntrySha256|test("^[a-f0-9]{64}$")) and (.runtimeSnapshotSha256|test("^[a-f0-9]{64}$")) and (.runtimeSnapshotShellSha256|test("^[a-f0-9]{64}$")) and (.fixtureHelperSha256|test("^[a-f0-9]{64}$"))' --arg ref "$REF" --arg base "$BASE" --arg candidate "$CANDIDATE" --arg manifest "$MANIFEST" "$INCOMING/stage-bindings.json" >/dev/null
payload=$(jq -r .runtimePayloadSha256 "$INCOMING/stage-bindings.json"); helper=$(jq -r .runtimeHelperSha256 "$INCOMING/stage-bindings.json"); observer=$(jq -r .observerHelperSha256 "$INCOMING/stage-bindings.json"); entry=$(jq -r .runtimeEntrySha256 "$INCOMING/stage-bindings.json"); snapshot=$(jq -r .runtimeSnapshotSha256 "$INCOMING/stage-bindings.json"); snapshot_shell=$(jq -r .runtimeSnapshotShellSha256 "$INCOMING/stage-bindings.json"); fixture_helper=$(jq -r .fixtureHelperSha256 "$INCOMING/stage-bindings.json")
[[ $(sha256sum "$INCOMING/runtime-files/runtime-files.sha256" | cut -d' ' -f1) == "$payload" && $(sha256sum "$INCOMING/runtime-acceptance.mjs" | cut -d' ' -f1) == "$helper" && $(sha256sum "$INCOMING/cgroup-observer.mjs" | cut -d' ' -f1) == "$observer" && $(sha256sum "$INCOMING/runtime-acceptance-entry.mjs" | cut -d' ' -f1) == "$entry" && $(sha256sum "$INCOMING/runtime-snapshot-export.mjs" | cut -d' ' -f1) == "$snapshot" && $(sha256sum "$INCOMING/export-acceptance-snapshot.sh" | cut -d' ' -f1) == "$snapshot_shell" && $(sha256sum "$INCOMING/prepare-acceptance-fixtures.mjs" | cut -d' ' -f1) == "$fixture_helper" ]] || { echo 'corrected incoming helper binding differs' >&2; exit 65; }
(cd "$INCOMING/runtime-files" && sha256sum --check runtime-files.sha256 >/dev/null)
[[ -z $(find -P "$INCOMING/runtime-files" -type l -print -quit) && -z $(find -P "$INCOMING/runtime-files" ! -type d ! -type f -print -quit) ]] || { echo 'corrected runtime payload has unsafe entries' >&2; exit 65; }
expected=$( { awk '/^[a-f0-9]{64}  / {print substr($0,67)}' "$INCOMING/runtime-files/runtime-files.sha256"; printf '%s\n' runtime-files.sha256 runtime-files-identity.json; } | LC_ALL=C sort); actual=$(find -P "$INCOMING/runtime-files" -type f -printf '%P\n' | LC_ALL=C sort); [[ $actual == "$expected" ]] || { echo 'corrected runtime payload inventory differs' >&2; exit 65; }
count=$(wc -l < "$INCOMING/runtime-files/runtime-files.sha256")
jq -e --arg candidate "$CANDIDATE" --arg manifest "$MANIFEST" --arg payload "$payload" --argjson count "$count" 'type=="object" and (keys|sort)==["candidate","fileCount","format","payloadManifestSha256","sourceManifestSha256"] and .format=="orloom-c3-acceptance-runtime-v1" and .candidate==$candidate and .sourceManifestSha256==$manifest and .payloadManifestSha256==$payload and .fileCount==$count' "$INCOMING/runtime-files/runtime-files-identity.json" >/dev/null
bundle=$(sha256sum "$INCOMING/candidate.bundle" | cut -d' ' -f1)
jq -e --arg base "$BASE" --arg candidate "$CANDIDATE" --arg ref "$REF" --arg manifest "$MANIFEST" --arg bundle "$bundle" --arg payload "$payload" '.format=="orl-c3-suite-acceptance-transfer-v1" and .baseSha==$base and .candidateSha==$candidate and .sourceRef==$ref and .suiteManifestSha256==$manifest and .bundleSha256==$bundle and .payloadManifestSha256==$payload' "$INCOMING/candidate-identity.json" >/dev/null

install -m 0500 "$OLD_NODE" "$ROOT/staging/node"; cp -a --no-preserve=ownership "$INCOMING/runtime-files" "$ROOT/runtime-files"; install -m 0400 "$INCOMING/runtime-acceptance.mjs" "$ROOT/runtime-acceptance.mjs"; install -m 0400 "$INCOMING/cgroup-observer.mjs" "$ROOT/cgroup-observer.mjs"; install -m 0400 "$INCOMING/runtime-acceptance-entry.mjs" "$ROOT/runtime-acceptance-entry.mjs"; install -m 0400 "$INCOMING/runtime-snapshot-export.mjs" "$ROOT/runtime-snapshot-export.mjs"; install -m 0500 "$INCOMING/export-acceptance-snapshot.sh" "$ROOT/export-acceptance-snapshot.sh"; install -m 0400 "$INCOMING/prepare-acceptance-fixtures.mjs" "$ROOT/prepare-acceptance-fixtures.mjs"; install -m 0400 "$INCOMING/stage-bindings.json" "$ROOT/stage-bindings.json"
[[ $(sha256sum "$ROOT/staging/node" | cut -d' ' -f1) == "$NODE_SHA" && $(sha256sum "$ROOT/runtime-files/runtime-files.sha256" | cut -d' ' -f1) == "$payload" && $(sha256sum "$ROOT/runtime-acceptance.mjs" | cut -d' ' -f1) == "$helper" && $(sha256sum "$ROOT/cgroup-observer.mjs" | cut -d' ' -f1) == "$observer" && $(sha256sum "$ROOT/runtime-acceptance-entry.mjs" | cut -d' ' -f1) == "$entry" && $(sha256sum "$ROOT/runtime-snapshot-export.mjs" | cut -d' ' -f1) == "$snapshot" && $(sha256sum "$ROOT/export-acceptance-snapshot.sh" | cut -d' ' -f1) == "$snapshot_shell" && $(sha256sum "$ROOT/prepare-acceptance-fixtures.mjs" | cut -d' ' -f1) == "$fixture_helper" ]] && (cd "$ROOT/runtime-files" && sha256sum --check runtime-files.sha256 >/dev/null) || { echo 'staged corrected payload rehash failed' >&2; exit 65; }
if gitc -C "$ROOT/source" show-ref --verify --quiet "$REF"; then echo 'local source ref unexpectedly exists' >&2; exit 75; fi
gitc -C "$ROOT/source" update-ref "$REF" "$CANDIDATE" 0000000000000000000000000000000000000000
env -i PATH=/usr/bin:/bin HOME=/root ORLOOM_ACCEPTANCE_SOURCE_REPO="$ROOT/source" ORLOOM_ACCEPTANCE_CANDIDATE_SHA="$CANDIDATE" ORLOOM_ACCEPTANCE_BASE_SHA="$BASE" ORLOOM_ACCEPTANCE_SOURCE_REF="$REF" ORLOOM_ACCEPTANCE_FIXTURE_ROOT="$ROOT/fixtures" "$ROOT/staging/node" "$ROOT/prepare-acceptance-fixtures.mjs" >/dev/null
[[ -d "$ROOT/fixtures/objects.git" && ! -L "$ROOT/fixtures/objects.git" && -f "$ROOT/fixtures/fixtures.json" && ! -L "$ROOT/fixtures/fixtures.json" ]] || { echo 'controlled fixture preparation failed' >&2; exit 65; }
printf 'stage=PASS\ncandidate=%s\nbase=%s\nref=%s\nsource_manifest=%s\nsource_manifest_entries=%s\npayload=%s\nnode=%s\ncontinuation=corrected-incoming\n' "$CANDIDATE" "$BASE" "$REF" "$MANIFEST" "$(wc -l < "$ROOT/source/.agent/ORL-C3-SUITE-MANIFEST.sha256")" "$payload" "$NODE_SHA" > "$ROOT/staging/identity.txt"; chmod 0400 "$ROOT/staging/identity.txt"
